import Foundation
import SwiftData

/// Every exercise of both programs (his and hers, `ExerciseLibrary.json` generated by `Tools/exercise_library.py`): a machine
/// taken can be swapped for any of them, for the session running only. One not in this phone's store yet is created on pick.
enum ExerciseLibrary {
    struct Entry: Decodable, Hashable {
        var name: String
        var muscleGroup: String
        var unilateral: Bool
    }

    static let entries: [Entry] = {
        guard let url = Bundle.main.url(forResource: "ExerciseLibrary", withExtension: "json"), let data = try? Data(contentsOf: url) else { return [] }
        return (try? JSONDecoder().decode([Entry].self, from: data)) ?? []
    }()

    /// The store's exercises plus the library's missing ones, by name (a library entry is nil until picked).
    static func choices(stored: [Exercise], library: [Entry] = entries) -> [(name: String, muscleGroup: String, exercise: Exercise?)] {
        let names = Set(stored.map(\.name))
        let rows = stored.map { (name: $0.name, muscleGroup: $0.muscleGroup, exercise: Optional($0)) }
            + library.filter { !names.contains($0.name) }.map { (name: $0.name, muscleGroup: $0.muscleGroup, exercise: nil) }
        return rows.sorted { $0.name.localizedStandardCompare($1.name) == .orderedAscending }
    }

    /// The exercise named so in the store, created from the library entry when missing.
    static func exercise(named name: String, in context: ModelContext) -> Exercise? {
        if let found = try? context.fetch(FetchDescriptor<Exercise>(predicate: #Predicate { $0.name == name })).first { return found }
        guard let entry = entries.first(where: { $0.name == name }) else { return nil }
        let exercise = Exercise(name: entry.name, muscleGroup: entry.muscleGroup, isUnilateral: entry.unilateral)
        context.insert(exercise)
        return exercise
    }
}
